struct CQuadTreeElement : CMovableResource {            // CLocalDetailCacheMap::CQuadTreeElement (PDB, 76 bytes)
    CObjectCacheGroupCollection* ObjectCacheGroupCollections;   // +0x04
    CQuadTreeElement*  Children[4];                     // +0x08
