                }
                if (IsActiveThreadTerminating())
                    return;
            }
            if (StopWhistling == true) {
                if (IsActiveThreadTerminating())
                    return;
                while (StopWhistling) {
                    GSI->NewScriptFrame();
                    if (IsActiveThreadTerminating())
                        return;
                }
                if (IsActiveThreadTerminating())
                    return;
            }
            if (!GSI->IsSoundPlaying(SoundPlayed)) {
                if (IsActiveThreadTerminating())
                    return;
