{
    while (!GSI->IsRegionLoaded("KrakenChamber")) {
        GSI->NewScriptFrame();
        if (IsActiveThreadTerminating())
            return;
    }
    if (IsActiveThreadTerminating())
        return;
    if (!QuestStartScreenShown) {
