    }
    void EntitySetAlpha(const CScriptThing& t, float a, bool) { if (t.Id == 12) KeyAlpha = a; }
    void SetVillageLimbo(const CScriptThing& t, bool l) { if (t.Id == 13) Limbo = l; }
