    void Spawn(const char* name) { std::strcat(GSI->Log, name); std::strcat(GSI->Log, ";"); }
    void PhaseOne() { std::strcat(GSI->Log, "one;"); if (FailInPhaseOne) MissionFailed = true; }
    void PhaseTwo() { std::strcat(GSI->Log, "two;"); }
